const body = ($input.item.json && $input.item.json.body) || {};
const username = String(body.username || '').trim().toLowerCase().replace(/^@/, '').replace(/\/+$/, '');
const target_type = (body.target_type || 'influencer') === 'brand' ? 'brand' : 'influencer';
const scrape_mode = body.scrape_mode === 'refresh' ? 'refresh' : 'deep';
if (!username) throw new Error('Missing username');
return { json: { username, target_type, scrape_mode } };

const p = $input.item.json;
const targetType = $('Parse Input').item.json.target_type;
const inputUsername = $('Parse Input').item.json.username;

const facts = {
  username: p.username || inputUsername,
  full_name: p.fullName || '',
  bio: p.biography || '',
  business_address: p.businessAddress || null,
  business_category: p.businessCategoryName || null,
  is_business_account: !!p.isBusinessAccount,
  external_url: p.externalUrl || null,
  followers: p.followersCount || 0,
  posts: p.postsCount || 0,
  is_verified: !!p.verified,
  target_type: targetType
};

const prompt = 'You are an Instagram profile analyst for an Indian influencer marketing platform. Extract structured intelligence from this profile.\n\nProfile facts:\n' + JSON.stringify(facts, null, 2) + '\n\nReturn ONLY this JSON (no markdown, no commentary). Use null for fields you cannot infer:\n{\n  "contact_phone": "10-digit Indian mobile if found in bio (digits only, no +91)",\n  "contact_email": "email if found, else null",\n  "whatsapp_number": "if bio mentions WhatsApp/WA/DM with a number, else same as contact_phone if unclear, else null",\n  "city": "city in India inferred from bio/handle, else null",\n  "business_type": "high-level type (restaurant | cafe | salon | gym | clothing_brand | beauty_brand | food_blogger | fashion_creator | comedy_creator | educator | fitness_creator | other)",\n  "sub_industry": "specific niche (mandi | biryani | haircut | makeup | yoga | sarees | streetwear etc.)",\n  "primary_offering": "one short sentence: what they sell or post about",\n  "tone": "casual | professional | playful | salesy | aspirational",\n  "languages_used": ["english", "telugu", "hindi"],\n  "reachability_score": 0-100 integer\n}\n\nIMPORTANT: contact_phone is exactly 10 digits if Indian mobile (starts 6-9). Strip +91 / 91- prefix. If no real phone, null. Do not invent.';

const claudeBody = {
  model: 'claude-sonnet-4-20250514',
  max_tokens: 1024,
  messages: [{ role: 'user', content: prompt }]
};

return { json: { claude_body: claudeBody, _facts: facts, _raw: p } };

let intel = {};
try {
  const resp = $input.item.json;
  const txt = resp && resp.content && resp.content[0] && resp.content[0].text || '';
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) intel = JSON.parse(m[0]);
} catch (e) { intel = { _parse_error: e.message }; }
return { json: {
  contact_phone: intel.contact_phone || null,
  contact_email: intel.contact_email || null,
  whatsapp_number: intel.whatsapp_number || null,
  city: intel.city || null,
  business_type: intel.business_type || null,
  sub_industry: intel.sub_industry || null,
  primary_offering: intel.primary_offering || null,
  tone: intel.tone || null,
  languages_used: Array.isArray(intel.languages_used) ? intel.languages_used : [],
  reachability_score: typeof intel.reachability_score === 'number' ? intel.reachability_score : 0,
  _parse_error: intel._parse_error || null
} };

const p = $('Get Scrape Results').item.json;
const targetType = $('Parse Input').item.json.target_type;
const inputUsername = $('Parse Input').item.json.username;
const intel = $('Parse Profile Intel').item.json;

const f = p.followersCount || 0;
let tier = 'nano';
if (targetType === 'influencer') {
  if (f >= 5000000) tier = 'celebrity';
  else if (f >= 1000000) tier = 'mega';
  else if (f >= 200000) tier = 'macro';
  else if (f >= 50000) tier = 'mid';
  else if (f >= 10000) tier = 'micro';
} else {
  if (f >= 200000) tier = 'enterprise';
  else if (f >= 50000) tier = 'large';
  else if (f >= 5000) tier = 'mid';
  else tier = 'small';
}

let er = 0;
if (p.latestPosts && p.latestPosts.length > 0 && f > 0) {
  const totalEng = p.latestPosts.reduce((s, post) => s + (post.likesCount || 0) + (post.commentsCount || 0), 0);
  er = Number(((totalEng / p.latestPosts.length) / f * 100).toFixed(4));
}
if (er > 99.99) er = 99.99;

const cleanUsername = (p.username || inputUsername || '').trim().toLowerCase();

// IMPORTANT: NEVER write to admin-manual fields:
//   city, niche/industry, sub_niche/sub_industry, manual_phone/email/whatsapp
// Claude data goes ONLY to inferred_* and bio_* columns.
const common = {
  followers_count: f,
  following_count: p.followsCount || 0,
  total_posts_lifetime: p.postsCount || 0,
  bio: p.biography || '',
  profile_pic_url: p.profilePicUrlHD || p.profilePicUrl || '',
  external_url: p.externalUrl || null,
  is_verified: !!p.verified,
  is_business: !!p.isBusinessAccount,
  is_private: !!p.private,
  ig_category: p.businessCategoryName || null,
  full_name: p.fullName || cleanUsername,
  // Claude-inferred
  bio_phone: intel.contact_phone,
  bio_email: intel.contact_email,
  bio_whatsapp: intel.whatsapp_number,
  primary_offering: intel.primary_offering,
  tone: intel.tone,
  bio_business_type: intel.business_type,
  reachability_score: intel.reachability_score,
  contact_intel_extracted_at: new Date().toISOString(),
  raw_profile_data: p,
  last_scraped_at: new Date().toISOString(),
  scrape_count: 1
};

if (targetType === 'brand') {
  return { json: {
    __target_type: 'brand',
    __username: cleanUsername,
    __endpoint: '/brand-metrics',
    __body: {
      instagram_handle: cleanUsername,
      business_name: p.fullName || p.username || cleanUsername,
      tier,
      inferred_city: intel.city,
      inferred_industry: intel.business_type,
      inferred_sub_industry: intel.sub_industry,
      languages_used: intel.languages_used,
      ...common
    }
  } };
}

return { json: {
  __target_type: 'influencer',
  __username: cleanUsername,
  __endpoint: '/creator-metrics',
  __body: {
    ig_handle: cleanUsername,
    follower_tier: tier,
    follower_based_er: er,
    inferred_city: intel.city,
    inferred_niche: intel.business_type,
    inferred_sub_niche: intel.sub_industry,
    languages: intel.languages_used,
    ...common
  }
} };
